"""Generate docs/module5_evidence_register.md from dashboard/data/dashboard_evidence.json (so every figure is copied, not retyped).
Run: python scripts/build_module5_docs.py"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]; E = json.loads((ROOT / "dashboard/data/dashboard_evidence.json").read_text())
M, H, F = E["meta"], E["headline"], E["fairness"]; L, B, ci = H["logreg"], H["baseline_recency_rule"], H["logreg_ci"]; c = F["comparisons"]["Non-UK"]; t = {r["group"]: r for r in F["table"]}
ver = f"churn_logreg v{M['model_version']}; dataset hash {M['dataset_hash']}"; pop = f"Held-out test, {M['test_rows']:,} customer-snapshots, {M['test_customers']:,} customers, Aug-Sep 2011"
thr = f"threshold {M['threshold']:.6f}"
rows = [
 ("E1", f"ROC-AUC {L['roc_auc']:.3f} (95% CI {ci['roc_auc'][0]:.3f}-{ci['roc_auc'][1]:.3f}) vs {B['roc_auc']:.3f} for a recency rule", "reports/model/final_test_results.json; Validation Report Table 2", ver, pop, "Area under ROC curve; customer-clustered bootstrap CI; threshold-free", "One test window; test set scored four times plus exploratory runs (disclosed); about half of test rows are customers with no purchase in the prior 180 days", "Slides 4-5; dashboard Results"),
 ("E2", f"At {thr}: precision {L['precision']:.3f}, recall {L['recall']:.3f}, F1 {L['f1']:.3f}, flag rate {L['flag_rate']:.3f}", "final_test_results.json; Model Card s4", ver, pop, f"tp {L['tp']:,}, fp {L['fp']:,}, fn {L['fn']:,}, tn {L['tn']:,}; precision = tp/(tp+fp); recall = tp/(tp+fn)", "Threshold maximises F1 on validation; test churn rate is 0.60 and the flag rate 0.81, so precision is a lift of only about 1.18 over the base rate", "Slides 4, 5; dashboard Overview"),
 ("E3", f"Flagging the top 20% gives precision {E['operating_points'][0]['precision']:.3f}, recall {E['operating_points'][0]['recall']:.3f}", "final_test_results.json operating_points", ver, pop, "Threshold set to flag a fixed share of customers", "Operating points computed on test for illustration; not a tuned recommendation", "Slide 5; dashboard Results"),
 ("E4", f"Mean score {M['mean_score']:.3f} vs observed churn {M['prevalence']:.3f}; scores not recalibrated", "final_test_results.json; Validation Report Section 4; Model Card caveat 6", ver, pop, "Mean predicted probability vs prevalence; decile table", "Churn rate differs between periods; scores are for ranking, not guaranteed frequencies", "Slides 4, 10; dashboard Results"),
 ("E5", "Purchase frequency, spend, product breadth and purchase regularity drive predictions; associations not causes", "reports/model/explainability_results.json global_shap", ver, "2,000 random test rows, 500 training background rows", "Mean |SHAP| on log-odds scale (LinearExplainer)", "LightGBM agrees on 2 of top 5 features (rank corr. 0.28); correlated features share credit", "Slide 6; dashboard Results"),
 ("E6", "Five held-out cases A-E chosen by a deterministic rule, including a false alarm and a missed churner", "explainability_results.json local, case_selection_rule", ver, "Test rows chosen by rule", "Top 4 SHAP drivers per case; log-odds", "Single cases illustrate, not prove; profiles rounded for the public dashboard", "Slide 7; dashboard Results"),
 ("E7", f"Counterfactual search: {E['counterfactuals']['batch']['feasible_share']:.1%} of {E['counterfactuals']['batch']['n_flagged_sampled']} flagged customers fall below the threshold within 6 extra invoices; median {E['counterfactuals']['batch']['median_extra_invoices']:.0f}", "explainability_results.json counterfactuals; explain.py", ver, "300 sampled flagged test customers", "Grid of 6 invoice counts x 6 recency options, re-scored through the pipeline", "Describes model response, not what would make a customer stay", "Slide 8; dashboard what-if"),
 ("E8", "Sensitivity: noise and recency shifts change AUC by about 0.001 or less", "explainability_results.json sensitivity", ver, "Test set, 10 repeats for noise", "Change in ROC-AUC; share of flags that flip", "Tests input noise, not behavioural change", "Slides 8, 14; dashboard About"),
 ("E9", f"Fairness (UK vs non-UK): DI {c['disparate_impact_ratio']:.3f}; DPD {c['demographic_parity_difference']:+.3f}; TPR diff {c['tpr_difference']:+.3f}; FPR diff {c['fpr_difference']:+.3f} (CI {c['ci_fpr_difference'][0]:.3f} to {c['ci_fpr_difference'][1]:.3f}); FPR/overall {c['fpr_vs_overall']:.3f}", "final_test_results.json fairness; Fairness_Metrics_Report.md", ver, f"UK n={t['UK']['n']:,}; non-UK n={t['Non-UK']['n']:,}", "Flag = positive; reference UK; bands DI 0.80-1.25, rates within 10% of overall", "UK vs non-UK is NOT a protected attribute; no protected attributes in data; bands are governance thresholds", "Slide 9; dashboard Fairness"),
 ("E10", "Two mitigations (ThresholdOptimizer, reweighing) were run; no band was breached on test, so neither was needed or adopted; group thresholds cut recall from 0.953 to 0.880", "reports/model/mitigation_results.json", ver, "Validation fit; test numbers exploratory", "Group FPR and recall before and after", "Mitigation test numbers are exploratory (test already scored)", "Slides 9, 14; dashboard Fairness"),
 ("E11", "Only the UK, Germany and France meet the minimum group size (100) among countries", "final_test_results.json fairness.per_country", ver, pop, "Customer-snapshots per country", "Small groups give wide intervals", "Slide 9; dashboard Fairness"),
 ("E12", "Registered model retail-churn-logreg version 3 alias champion; artefact byte-identical to the served model", "reports/mlflow_evidence/model_registry.json", ver, "n/a", "SHA-256 equality", "Alias is not production approval; local store", "Slides 13, 15; dashboard About"),
 ("E13", "API /predict returns the same score as the serialised model (parity to 6 decimals); invalid input returns 422 without echoing values", "scripts/api_demo.py; reports/evidence/api_demo_output.txt; tests/test_dashboard.py", ver, "Demo request", "6 expectations in demo script", "Demonstrated against a local API; hosted instance is internal to the Space", "Slide 15"),
 ("E14", "Dashboard filter figures reproduce the recorded confusion matrix", "dashboard/dash_lib/core.py; tests/test_dashboard.py", ver, "Filter grid (month x group)", "Metrics recomputed from stored counts at the fixed threshold", "AUC is precomputed per filter combination; fairness view is static", "Dashboard"),
 ("E15", "No protected attributes exist; none inferred; 90-day churn window and eligibility rule (at least 180 days of prior history) confirmed by email from the Marketing Director, 1 Nov 2026", "Model Card s3, s8; Validation Report Section 2", ver, "n/a", "n/a", "Instructor clarification request drafted; send status is the author's", "Slides 3, 9, 10, 14"),
 ("E16", "Customer-segment audit (behavioural, not protected): fixed threshold flags " + f"{E['segment_audit']['dimensions']['frequency_tier']['tiers']['Low']['flag_rate']:.0%}" + " of customers with two or fewer invoices", "reports/model/segment_audit.json; scripts/segment_audit.py; Fairness Metrics Report Section 7", ver, pop, "Flag rate, TPR, FPR by tertile of tenure, spend, purchase frequency; cut-offs from training snapshots; Wilson 95% intervals", "Exploratory and descriptive; further look at the test period; not a fairness test; Module 1 bands not applied", "Appendix B; dashboard Fairness and ethics"),
]
out = ["# Module 5 evidence register", "", "Every number below is generated from `dashboard/data/dashboard_evidence.json`, which is built from recorded Module 4 outputs by `scripts/build_dashboard_data.py`. Nothing was retrained.", "",
       "| ID | Claim or finding | Supporting artifact | Model / dataset version | Population and period | Metric definition, denominator, threshold | Limitations | Used in |", "|---|---|---|---|---|---|---|---|"]
out += ["| " + " | ".join(r) + " |" for r in rows]
out += ["", "## Consistency checks performed", "", "- Filter grid reproduces the recorded confusion matrix (`tests/test_dashboard.py`).", "- Dashboard what-if scenario logic equals the Module 4 `apply_scenario` for all example profiles and parameters (tests).", "- API score for each rounded example profile is within 0.002 of the stored evaluation score; Case E sits on the threshold, so rounding flips its flag (shown in the dashboard).", "- Validation report, Model Card, fairness report and API metadata agree on version, threshold and headline metrics (`scripts/verify_module4.py`, 23 checks).", "- The slide figures are read from the same JSON by `scripts/verify_module5.py`."]
(ROOT / "docs/module5_evidence_register.md").write_text("\n".join(out) + "\n"); print("wrote register with", len(rows), "rows")
